    g = [row[:] for row in grid]

    # The two matching boundary bars define the displacement of a repeated
    # vertical or horizontal pattern.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            if c and color == grid[r][c - 1]:
                c += 1
                continue
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if end - c >= 2:
                bars.append((r, c, end, color))
            c = end

    if len(bars) < 2:
        return g
    bars.sort()
    first, second = bars[0], bars[-1]
    shift = second[1] - first[1]

    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and
             not (r in (0, h - 1) and
                  any(br == r and start <= c < end
                      for br, start, end, _ in bars))]
    for r, c, color in seeds:
        # Copies of each seed are displaced by the offset between bars.
        for cc in (c, c + shift):
            if 0 <= cc < w:
                for rr in range(h):
                    if grid[rr][cc] == bg:
                        g[rr][cc] = color
                g[r][cc] = 4
    return g
