def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Locate the colored horizontal bars on the top and bottom edges.
    def runs(row):
        out = []
        c = 0
        while c < w:
            v = row[c]
            j = c + 1
            while j < w and row[j] == v:
                j += 1
            if j - c >= 2:
                out.append((c, j, v))
            c = j
        return out

    top = [x for x in runs(grid[0]) if x[2] != grid[0][0]]
    bot = [x for x in runs(grid[-1]) if x[2] != grid[-1][0]]
    if not top or not bot:
        return g
    a, b = top[0], bot[0]
    delta = b[0] - a[0]

    # Isolated marks are extended toward the nearest edge; their translated
    # counterpart is extended from the opposite edge. The mark becomes 4.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and counts[grid[r][c]] == 1]

    for r, c, color in seeds:
        g[r][c] = 4
        # Extend the seed column from the nearer boundary to the seed.
        if r <= h - 1 - r:
            for rr in range(1, r):
                g[rr][c] = color
        else:
            for rr in range(r + 1, h - 1):
                g[rr][c] = color

        # Repeated copy lies at the corresponding offset between the bars.
        cc = c + delta
        if 0 <= cc < w:
            if r <= h - 1 - r:
                for rr in range(0, r + 1):
                    g[rr][cc] = color
            else:
                for rr in range(r, h):
                    g[rr][cc] = color
    return g
